def blocks(g,col=8):
    seen=set(); out=[]
    for i in range(len(g)):
        for j in range(len(g[0])):
            if g[i][j]==col and (i,j) not in seen:
                stack=[(i,j)]; seen.add((i,j)); cells=[]
                while stack:
                    r,c=stack.pop(); cells.append((r,c))
                    for dr,dc in((1,0),(-1,0),(0,1),(0,-1)):
                        nr,nc=r+dr,c+dc
                        if 0<=nr<len(g) and 0<=nc<len(g[0]) and g[nr][nc]==col and (nr,nc) not in seen:
                            seen.add((nr,nc)); stack.append((nr,nc))
                rs=[r for r,_ in cells]; cs=[c for _,c in cells]
                out.append((min(rs),min(cs),max(rs),max(cs),len(cells)))
    return sorted(out)
