def rects(g, col=8):
    # decompose the 8-blob into maximal rectangles greedily (top-left first)
    g=[row[:] for row in g]; out=[]
    H,W=len(g),len(g[0])
    while True:
        best=None
        for i in range(H):
            for j in range(W):
                if g[i][j]==col:
                    w=0
                    while j+w<W and g[i][j+w]==col: w+=1
                    h=1
                    while i+h<H and all(g[i+h][j+k]==col for k in range(w)): h+=1
                    # prefer largest
                    if best is None or h*w>best[0]: best=(h*w,i,j,h,w)
        if best is None: break
        _,i,j,h,w=best
        out.append((i,j,h,w))
        for r in range(i,i+h):
            for c in range(j,j+w): g[r][c]=-1
    return out

def rect_colors(gi,go):
    out=[]
    for i,j,h,w in rects(gi):
        out.append((i,j,h,w,go[i+h//2][j+w//2]))
